// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(c *gin.Context)
	// GetReadyz Readiness probe (database reachable)
	// (GET /readyz)
	GetReadyz(c *gin.Context)

	// (GET /v1/account)
	GetAccount(c *gin.Context)

	// (PATCH /v1/account)
	UpdateAccount(c *gin.Context)
	// AcceptInvitation Accept an invitation by choosing a password (RF-41)
	// (POST /v1/auth/accept-invitation)
	AcceptInvitation(c *gin.Context)
	// Login Sign in with email and password
	// (POST /v1/auth/login)
	Login(c *gin.Context)
	// Logout Revoke a refresh token
	// (POST /v1/auth/logout)
	Logout(c *gin.Context)
	// RefreshSession Exchange a refresh token for a new session (rotation)
	// (POST /v1/auth/refresh)
	RefreshSession(c *gin.Context)
	// Signup Create an account (trial) with its first branch and owner (RF-S01)
	// (POST /v1/auth/signup)
	Signup(c *gin.Context)
	// ListBranches Branches the current user can access
	// (GET /v1/branches)
	ListBranches(c *gin.Context)

	// (POST /v1/branches)
	CreateBranch(c *gin.Context)

	// (GET /v1/branches/{branchId})
	GetBranch(c *gin.Context, branchId BranchId)

	// (PATCH /v1/branches/{branchId})
	UpdateBranch(c *gin.Context, branchId BranchId)
	// UpdateBranchSettings Replace the branch settings (RF-40)
	// (PUT /v1/branches/{branchId}/settings)
	UpdateBranchSettings(c *gin.Context, branchId BranchId)
	// ListCustomers Search customers by name, document, phone or email (RF-01, UC-01)
	// (GET /v1/customers)
	ListCustomers(c *gin.Context, params ListCustomersParams)
	// CreateCustomer Register a customer with its contacts (RF-01, RF-45)
	// (POST /v1/customers)
	CreateCustomer(c *gin.Context)

	// (GET /v1/customers/{customerId})
	GetCustomer(c *gin.Context, customerId CustomerId)

	// (PATCH /v1/customers/{customerId})
	UpdateCustomer(c *gin.Context, customerId CustomerId)

	// (POST /v1/customers/{customerId}/contacts)
	CreateContact(c *gin.Context, customerId CustomerId)

	// (DELETE /v1/customers/{customerId}/contacts/{contactId})
	DeleteContact(c *gin.Context, customerId CustomerId, contactId ContactId)

	// (PATCH /v1/customers/{customerId}/contacts/{contactId})
	UpdateContact(c *gin.Context, customerId CustomerId, contactId ContactId)
	// CreateCostCenter Add a cost center (department to bill) to a company customer (RF-45, RN-34)
	// (POST /v1/customers/{customerId}/cost-centers)
	CreateCostCenter(c *gin.Context, customerId CustomerId)

	// (PATCH /v1/customers/{customerId}/cost-centers/{costCenterId})
	UpdateCostCenter(c *gin.Context, customerId CustomerId, costCenterId CostCenterId)
	// GetCustomerHistory Service orders of a customer in the branches the user can access (RF-35)
	// (GET /v1/customers/{customerId}/history)
	GetCustomerHistory(c *gin.Context, customerId CustomerId, params GetCustomerHistoryParams)
	// ListDevices Installed desktop apps of the account
	// (GET /v1/devices)
	ListDevices(c *gin.Context)
	// ReserveNumberBlock Reserve a block of service order numbers for offline use (RN-04)
	// (POST /v1/devices/{deviceId}/number-blocks)
	ReserveNumberBlock(c *gin.Context, deviceId DeviceId)
	// RevokeDevice Revoke a lost or retired device (ADR-07)
	// (POST /v1/devices/{deviceId}/revoke)
	RevokeDevice(c *gin.Context, deviceId DeviceId)
	// ListEquipment Search equipment by serial number, brand or model (RF-02, RF-36)
	// (GET /v1/equipment)
	ListEquipment(c *gin.Context, params ListEquipmentParams)

	// (POST /v1/equipment)
	CreateEquipment(c *gin.Context)
	// ListEquipmentTypes Equipment types with their custom fields and entry checklist (RF-03)
	// (GET /v1/equipment-types)
	ListEquipmentTypes(c *gin.Context)

	// (POST /v1/equipment-types)
	CreateEquipmentType(c *gin.Context)

	// (GET /v1/equipment-types/{equipmentTypeId})
	GetEquipmentType(c *gin.Context, equipmentTypeId EquipmentTypeId)

	// (PUT /v1/equipment-types/{equipmentTypeId})
	UpdateEquipmentType(c *gin.Context, equipmentTypeId EquipmentTypeId)

	// (GET /v1/equipment/{equipmentId})
	GetEquipment(c *gin.Context, equipmentId EquipmentId)

	// (PATCH /v1/equipment/{equipmentId})
	UpdateEquipment(c *gin.Context, equipmentId EquipmentId)
	// GetEquipmentHistory Service orders of an equipment with its active warranties (RF-36)
	// (GET /v1/equipment/{equipmentId}/history)
	GetEquipmentHistory(c *gin.Context, equipmentId EquipmentId, params GetEquipmentHistoryParams)
	// GetMe Current user, account, grants and accessible branches
	// (GET /v1/me)
	GetMe(c *gin.Context)
	// ApplyNichePack Add the equipment types, checklists and services of a niche pack (RF-08)
	// (POST /v1/niche-packs/{packCode}/apply)
	ApplyNichePack(c *gin.Context, packCode string)
	// ListProducts Products and parts by name, SKU or barcode (RF-05)
	// (GET /v1/products)
	ListProducts(c *gin.Context, params ListProductsParams)
	// CreateProduct Add a product or part
	// (POST /v1/products)
	CreateProduct(c *gin.Context)

	// (GET /v1/products/{productId})
	GetProduct(c *gin.Context, productId ProductId)

	// (PATCH /v1/products/{productId})
	UpdateProduct(c *gin.Context, productId ProductId)
	// ListServiceOrders Queue and search of the branch's orders (RF-11, RF-17)
	// (GET /v1/service-orders)
	ListServiceOrders(c *gin.Context, params ListServiceOrdersParams)
	// OpenServiceOrder Open a service order (UC-01, RN-04, RN-05)
	// (POST /v1/service-orders)
	OpenServiceOrder(c *gin.Context, params OpenServiceOrderParams)

	// (GET /v1/service-orders/{orderId})
	GetServiceOrder(c *gin.Context, orderId OrderId, params GetServiceOrderParams)
	// UpdateServiceOrder Record diagnosis, technical report and other details (RF-12, RF-14)
	// (PATCH /v1/service-orders/{orderId})
	UpdateServiceOrder(c *gin.Context, orderId OrderId, params UpdateServiceOrderParams)
	// AbandonServiceOrder Mark the equipment as abandoned after the branch's term (RN-16)
	// (POST /v1/service-orders/{orderId}/abandon)
	AbandonServiceOrder(c *gin.Context, orderId OrderId, params AbandonServiceOrderParams)
	// AssignServiceOrder Assign the technician and the priority (RF-11)
	// (PATCH /v1/service-orders/{orderId}/assignment)
	AssignServiceOrder(c *gin.Context, orderId OrderId, params AssignServiceOrderParams)
	// CancelServiceOrder Cancel the order with a reason (RN-08)
	// (POST /v1/service-orders/{orderId}/cancel)
	CancelServiceOrder(c *gin.Context, orderId OrderId, params CancelServiceOrderParams)
	// DeliverServiceOrder Hand the equipment back (UC-05, RN-15, RN-18, RN-31)
	// (POST /v1/service-orders/{orderId}/deliver)
	DeliverServiceOrder(c *gin.Context, orderId OrderId, params DeliverServiceOrderParams)
	// RevealDevicePassword Show the equipment password; every access is audited (RN-31)
	// (POST /v1/service-orders/{orderId}/device-password/reveal)
	RevealDevicePassword(c *gin.Context, orderId OrderId, params RevealDevicePasswordParams)
	// ListOrderStatusHistory Status changes of the order, oldest first (RN-07)
	// (GET /v1/service-orders/{orderId}/history)
	ListOrderStatusHistory(c *gin.Context, orderId OrderId, params ListOrderStatusHistoryParams)
	// ListQuotes Every quote version of the order (RN-11)
	// (GET /v1/service-orders/{orderId}/quotes)
	ListQuotes(c *gin.Context, orderId OrderId, params ListQuotesParams)
	// CreateQuote Start a quote draft (RF-12)
	// (POST /v1/service-orders/{orderId}/quotes)
	CreateQuote(c *gin.Context, orderId OrderId, params CreateQuoteParams)
	// UpdateQuote Replace the notes and items of a draft
	// (PUT /v1/service-orders/{orderId}/quotes/{quoteId})
	UpdateQuote(c *gin.Context, orderId OrderId, quoteId QuoteId, params UpdateQuoteParams)
	// DecideQuote Record the customer's approval or rejection (UC-03, RN-10, RN-14, RN-34)
	// (POST /v1/service-orders/{orderId}/quotes/{quoteId}/decision)
	DecideQuote(c *gin.Context, orderId OrderId, quoteId QuoteId, params DecideQuoteParams)
	// SendQuote Send the draft to the customer (RN-09, RN-10, RN-11)
	// (POST /v1/service-orders/{orderId}/quotes/{quoteId}/send)
	SendQuote(c *gin.Context, orderId OrderId, quoteId QuoteId, params SendQuoteParams)
	// TransitionServiceOrder Move the order through diagnosis and execution (section 8, RN-07)
	// (POST /v1/service-orders/{orderId}/transitions)
	TransitionServiceOrder(c *gin.Context, orderId OrderId, params TransitionServiceOrderParams)
	// OpenWarrantyReturn Open a warranty return linked to a delivered order (UC-07, RN-19)
	// (POST /v1/service-orders/{orderId}/warranty-return)
	OpenWarrantyReturn(c *gin.Context, orderId OrderId, params OpenWarrantyReturnParams)
	// ListServices Service catalog (RF-04)
	// (GET /v1/services)
	ListServices(c *gin.Context, params ListServicesParams)
	// CreateService Add a service to the catalog
	// (POST /v1/services)
	CreateService(c *gin.Context)

	// (GET /v1/services/{serviceId})
	GetService(c *gin.Context, serviceId ServiceId)

	// (PATCH /v1/services/{serviceId})
	UpdateService(c *gin.Context, serviceId ServiceId)
	// ListSuppliers Suppliers (RF-06)
	// (GET /v1/suppliers)
	ListSuppliers(c *gin.Context, params ListSuppliersParams)
	// CreateSupplier Add a supplier
	// (POST /v1/suppliers)
	CreateSupplier(c *gin.Context)

	// (GET /v1/suppliers/{supplierId})
	GetSupplier(c *gin.Context, supplierId SupplierId)

	// (PATCH /v1/suppliers/{supplierId})
	UpdateSupplier(c *gin.Context, supplierId SupplierId)

	// (GET /v1/users)
	ListUsers(c *gin.Context)
	// InviteUser Invite a user by email with roles per branch (RF-41)
	// (POST /v1/users/invitations)
	InviteUser(c *gin.Context)

	// (GET /v1/users/{userId})
	GetUser(c *gin.Context, userId UserId)
	// DisableUser Disable a user and end their sessions
	// (POST /v1/users/{userId}/disable)
	DisableUser(c *gin.Context, userId UserId)

	// (POST /v1/users/{userId}/enable)
	EnableUser(c *gin.Context, userId UserId)
	// UpdateUserGrants Replace the roles and branches of a user
	// (PUT /v1/users/{userId}/grants)
	UpdateUserGrants(c *gin.Context, userId UserId)
}

